-- -------------------------------------------------------------------------
-- S6. Cập nhật Author Profile: authorCoinBalance = tích lũy tháng 07/2026
--     (Doanh thu xu từ chapter unlocks tháng này, chưa quyết toán)
-- -------------------------------------------------------------------------
UPDATE author_profiles
SET author_coin_balance = 2340,
    total_views         = 31200,
    total_chapters      = 421,
    updated_at          = CURRENT_TIMESTAMP
WHERE user_id = '70eb648d-5444-5a43-bde1-06f8dab7d62a';

-- Cập nhật tất cả các chương dùng xu (LOCKED) thành 10 xu
UPDATE chapters
SET coin_price = 10
WHERE status = 'LOCKED' OR coin_price > 0;

-- -------------------------------------------------------------------------
-- S7. Verify thống kê sau khi seed
-- -------------------------------------------------------------------------
SELECT 'Orders (COMPLETED)'  AS stat, COUNT(*) AS cnt FROM orders WHERE status = 'COMPLETED'
UNION ALL SELECT 'New Users',          COUNT(*) FROM users WHERE email LIKE 'user%@sba.com' AND email != 'user@sba.com'
UNION ALL SELECT 'Chapter Unlocks',    COUNT(*) FROM chapter_unlocks
UNION ALL SELECT 'Coin Transactions',  COUNT(*) FROM coin_transactions
UNION ALL SELECT 'Payment Tickets',    COUNT(*) FROM author_payment_tickets;

-- =============================================================================
-- SINGLE NOVEL BELL-CURVE DEMO (Empire of Glass = novel_id 10)
-- NOTE: Đoạn này dùng DECLARE / CURSOR nên phải chạy thủ công trong SSMS.
--       Spring SQL init không hỗ trợ T-SQL batch với biến cục bộ.
-- =============================================================================

/*  ← bỏ comment để chạy thủ công trong SSMS

DECLARE @TargetNovelId BIGINT = 10;

-- =============================================================================
-- 1. RESET dữ liệu cũ của novel này
-- =============================================================================

DELETE ct
FROM coin_transactions ct
JOIN chapter_unlocks cu ON ct.user_id = cu.user_id
JOIN chapters ch ON cu.chapter_id = ch.id
WHERE ch.novel_id = @TargetNovelId
  AND ct.type = 'UNLOCKED_CHAPTER';

DELETE cu
FROM chapter_unlocks cu
JOIN chapters ch ON cu.chapter_id = ch.id
WHERE ch.novel_id = @TargetNovelId;

DELETE FROM revenues WHERE novel_id = @TargetNovelId;

-- =============================================================================
-- 2. VIEW COUNT HÌNH CHUÔNG
-- Peak ở chapter giữa (khoảng 33)
-- =============================================================================

;WITH ChapterPosition AS (
    SELECT
        id,
        chapter_number,
        ABS(chapter_number - 33) AS distance_from_peak
    FROM chapters
    WHERE novel_id = @TargetNovelId
)
UPDATE c
SET view_count =
    CASE
        WHEN cp.distance_from_peak = 0 THEN 1800
        WHEN cp.distance_from_peak <= 2 THEN 1650
        WHEN cp.distance_from_peak <= 5 THEN 1450
        WHEN cp.distance_from_peak <= 8 THEN 1250
        WHEN cp.distance_from_peak <= 12 THEN 1050
        WHEN cp.distance_from_peak <= 16 THEN 850
        WHEN cp.distance_from_peak <= 20 THEN 650
        WHEN cp.distance_from_peak <= 25 THEN 450
        ELSE 250
    END
FROM chapters c
JOIN ChapterPosition cp ON c.id = cp.id;

-- =============================================================================
-- 3. PHÂN PHỐI NGƯỜI MUA HÌNH CHUÔNG
-- 2,3,5,8,12,15,12,9,5,3
-- =============================================================================

DECLARE @Readers TABLE (
    user_id UNIQUEIDENTIFIER,
    unlock_count INT
);


-- Insert unlocks theo phân phối hình chuông
    id,
    user_id,
    chapter_id,
    coins_spent,
    unlocked_at
)
SELECT
    NEWID(),
    r.user_id,
    c.id,
    15,
    DATEADD(
        DAY,
        -20 + ROW_NUMBER() OVER (
            PARTITION BY r.user_id
            ORDER BY c.chapter_number
        ),
        SYSUTCDATETIME()
    )
FROM @Readers r
CROSS APPLY (
    SELECT TOP (r.unlock_count)
        c.id,
        c.chapter_number
    FROM chapters c
    WHERE c.novel_id = @TargetNovelId
      AND c.status = 'LOCKED'
    ORDER BY c.chapter_number
) c;

-- Coin transactions tương ứng
    id,
    user_id,
    type,
    amount,
    balance_after,
    note,
    created_at
)
SELECT
    NEWID(),
    cu.user_id,
    'UNLOCKED_CHAPTER',
    -15,
    0,
    'Unlock chapter: Empire of Glass - Ch.' + CAST(ch.chapter_number AS VARCHAR),
    cu.unlocked_at
FROM chapter_unlocks cu
JOIN chapters ch ON cu.chapter_id = ch.id
WHERE ch.novel_id = @TargetNovelId;

-- =============================================================================
-- 4. DOANH THU = n x 15
-- n = tổng số chapter đã được mua
-- =============================================================================

    novel_id,
    author_id,
    total_coins_earned,
    free_chapter_count,
    total_chapter_count,
    author_share_percent,
    author_coins,
    calculated_at
)
SELECT
    n.id,
    n.author_id,

    -- n x 15
    COUNT(cu.id) * 15 AS total_coins_earned,

    SUM(CASE WHEN c.status = 'FREE' THEN 1 ELSE 0 END) AS free_chapter_count,

    COUNT(c.id) AS total_chapter_count,

    70.00 AS author_share_percent,

    CAST(COUNT(cu.id) * 15 * 0.70 AS INT) AS author_coins,

    SYSUTCDATETIME()
FROM novels n
LEFT JOIN chapters c
    ON c.novel_id = n.id
LEFT JOIN chapter_unlocks cu
    ON cu.chapter_id = c.id
WHERE n.id = @TargetNovelId
GROUP BY n.id, n.author_id;

-- =============================================================================
-- 5. VERIFY
